s10-longest-substring-without-repeating-.code:
// Approach: Remember each character's latest index. If it lies inside the current window, move the
//   left boundary just past it.
#include <algorithm>
#include <array>
#include <string>
using namespace std;
int longestUniqueSubstring(const string& s) {
    // Move the left edge past a repeated character's earlier position.
    array<int, 256> last;
    last.fill(-1);
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        unsigned char ch = (unsigned char)s[right];
        left = max(left, last[ch] + 1);
        last[ch] = right;
        best = max(best, right - left + 1);
    }
    return best;
}

s10-max-consecutive-ones-iii.code:
// Approach: Maintain a window with at most k zeroes. When it has too many, move its left edge until
//   valid again.
#include <algorithm>
#include <vector>
using namespace std;
int longestOnes(const vector<int>& a, int k) {
    // Expand right; move left only when the window contains too many zeros.
    if (k < 0) return 0;
    int left = 0, zeros = 0, best = 0;
    for (int right = 0; right < (int)a.size(); ++right) {
        if (a[right] == 0) ++zeros;
        while (zeros > k) {
            if (a[left] == 0) --zeros;
            ++left;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

s10-fruit-into-baskets.code:
// Approach: A valid window contains at most two fruit types. Count types in a map and shrink when a
//   third appears.
#include <algorithm>
#include <unordered_map>
#include <vector>
using namespace std;
int totalFruit(const vector<int>& fruit) {
    // Keep at most two fruit types inside the current window.
    unordered_map<int, int> count;
    int left = 0, best = 0;
    for (int right = 0; right < (int)fruit.size(); ++right) {
        ++count[fruit[right]];
        while (count.size() > 2) {
            if (--count[fruit[left]] == 0) count.erase(fruit[left]);
            ++left;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

s10-longest-repeating-character-replacem.code:
// Approach: For uppercase letters, a window is valid when its length minus its most frequent letter
//   count is at most k. Shrink until valid.
#include <algorithm>
#include <array>
#include <string>
using namespace std;
int characterReplacement(const string& s, int k) {
    if (k < 0) return 0;
    array<int, 26> count{};
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        ++count[s[right] - 'A']; // problem guarantees A-Z
        while (true) {
            int most = *max_element(count.begin(), count.end());
            if (right - left + 1 - most <= k) break;
            --count[s[left] - 'A'];
            ++left;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

s10-binary-subarray-with-sum.code:
// Approach: For a binary array, count subarrays with sum at most goal, then subtract those with sum
//   at most goal-1.
#include <vector>
using namespace std;
long long binaryAtMost(const vector<int>& a, int limit) {
    // Exactly-goal equals at-most-goal minus at-most-(goal-1).
    if (limit < 0) return 0;
    int left = 0, sum = 0;
    long long count = 0;
    for (int right = 0; right < (int)a.size(); ++right) {
        sum += a[right];
        while (sum > limit) sum -= a[left++];
        count += right - left + 1;
    }
    return count;
}
long long binarySubarraysWithSum(const vector<int>& a, int goal) {
    return binaryAtMost(a, goal) - binaryAtMost(a, goal - 1);
}

s10-count-number-of-nice-subarrays.code:
// Approach: Count windows containing at most k odd values, then subtract those with at most k-1 odds.
#include <vector>
using namespace std;
long long atMostOdds(const vector<int>& a, int k) {
    if (k < 0) return 0;
    int left = 0, odd = 0;
    long long count = 0;
    // Count subarrays with at most k odd values, then subtract at most k-1.
    for (int right = 0; right < (int)a.size(); ++right) {
        odd += a[right] % 2 != 0;
        while (odd > k) odd -= a[left++] % 2 != 0;
        count += right - left + 1;
    }
    return count;
}
long long numberOfNiceSubarrays(const vector<int>& a, int k) {
    return atMostOdds(a, k) - atMostOdds(a, k - 1);
}

s10-number-of-substring-containing-all-t.code:
// Approach: Track the latest positions of a, b and c. For every right endpoint, all starts up to the
//   earliest of those positions form valid substrings.
#include <algorithm>
#include <array>
#include <string>
using namespace std;
long long numberOfSubstringsABC(const string& s) {
    // Once all three are present, every longer suffix also works.
    array<int, 3> last{-1, -1, -1};
    long long answer = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        if (s[i] >= 'a' && s[i] <= 'c') last[s[i] - 'a'] = i;
        int earliest = min({last[0], last[1], last[2]});
        if (earliest >= 0) answer += earliest + 1;
    }
    return answer;
}

s10-maximum-point-you-can-obtain-from-ca.code:
// Approach: Start with k cards from the left. Repeatedly replace one left card with one from the
//   right and keep the maximum sum.
#include <algorithm>
#include <vector>
using namespace std;
long long maxScore(const vector<int>& cards, int k) {
    // Choosing ends is equivalent to leaving one middle window unchosen.
    int n = (int)cards.size();
    if (k < 0 || k > n) return 0;
    long long sum = 0;
    for (int i = 0; i < k; ++i) sum += cards[i];
    long long best = sum;
    for (int takeRight = 1; takeRight <= k; ++takeRight) {
        sum -= cards[k - takeRight];
        sum += cards[n - takeRight];
        best = max(best, sum);
    }
    return best;
}

s10-longest-substring-with-at-most-k-dis.code:
// Approach: Count characters in the current window. When it contains more than k distinct characters,
//   shrink it from the left.
#include <algorithm>
#include <string>
#include <unordered_map>
using namespace std;
int longestAtMostKDistinct(const string& s, int k) {
    // Shrink the window whenever its distinct count exceeds k.
    if (k <= 0) return 0;
    unordered_map<char, int> count;
    int left = 0, best = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        ++count[s[right]];
        while ((int)count.size() > k) {
            if (--count[s[left]] == 0) count.erase(s[left]);
            ++left;
        }
        best = max(best, right - left + 1);
    }
    return best;
}

s10-subarray-with-k-different-integers.code:
// Approach: Exactly k distinct equals at most k distinct minus at most k-1 distinct. Each at-most
//   count uses a shrinking frequency-map window.
#include <unordered_map>
#include <vector>
using namespace std;
long long atMostDistinct(const vector<int>& a, int k) {
    // Subtract at-most-(k-1) from at-most-k to get exactly k.
    if (k < 0) return 0;
    unordered_map<int, int> count;
    int left = 0;
    long long answer = 0;
    for (int right = 0; right < (int)a.size(); ++right) {
        ++count[a[right]];
        while ((int)count.size() > k) {
            if (--count[a[left]] == 0) count.erase(a[left]);
            ++left;
        }
        answer += right - left + 1;
    }
    return answer;
}
long long subarraysWithKDistinct(const vector<int>& a, int k) {
    return atMostDistinct(a, k) - atMostDistinct(a, k - 1);
}

s10-minimum-window-substring.code:
// Approach: Expand until the window contains every required character (including duplicates), then
//   shrink from the left while preserving that condition.
#include <array>
#include <string>
using namespace std;
string minWindow(const string& s, const string& t) {
    // Track required counts and shrink only while the window remains valid.
    if (t.empty()) return "";
    array<int, 256> need{};
    for (unsigned char ch : t) ++need[ch];
    int missing = (int)t.size(), left = 0;
    int bestStart = -1, bestLength = (int)s.size() + 1;
    for (int right = 0; right < (int)s.size(); ++right) {
        unsigned char ch = (unsigned char)s[right];
        if (need[ch] > 0) --missing;
        --need[ch];
        while (missing == 0) {
            int length = right - left + 1;
            if (length < bestLength) {
                bestLength = length;
                bestStart = left;
            }
            unsigned char outgoing = (unsigned char)s[left++];
            if (++need[outgoing] > 0) ++missing;
        }
    }
    return bestStart < 0 ? "" : s.substr(bestStart, bestLength);
}

s10-minimum-window-subsequence.code:
// Approach: Dynamic programming stores the latest start index of a source prefix matching each prefix
//   of the target as a subsequence. Update target positions backwards per source character.
#include <string>
#include <vector>
using namespace std;
string minWindowSubsequence(const string& s, const string& t) {
    // Match the target in order, then move backward to tighten the start.
    if (t.empty()) return "";
    vector<int> start(t.size(), -1);
    int bestStart = -1, bestLength = (int)s.size() + 1;
    for (int i = 0; i < (int)s.size(); ++i) {
        for (int j = (int)t.size() - 1; j >= 0; --j) {
            if (s[i] != t[j]) continue;
            if (j == 0) start[j] = i;
            else if (start[j - 1] != -1) start[j] = start[j - 1];
        }
        int from = start.back();
        if (from != -1 && i - from + 1 < bestLength) {
            bestLength = i - from + 1;
            bestStart = from;
        }
    }
    return bestStart < 0 ? "" : s.substr(bestStart, bestLength);
}
